<style>.legacy-pos{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(330px,.72fr);gap:16px;align-items:start}.pos-catalog{min-width:0}.pos-toolbar{display:flex;gap:10px;align-items:center;margin-bottom:12px}.pos-search{flex:1}.pos-categories{display:flex;gap:6px;overflow:auto;margin-bottom:14px;padding-bottom:4px}.pos-cat{border:1px solid var(--line);background:#fff;color:#66667a;border-radius:999px;padding:9px 13px;font-size:11px;font-weight:850;white-space:nowrap;cursor:pointer}.pos-cat.active{background:var(--accent);color:#fff;border-color:var(--accent)}.pos-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.pos-product{background:#fff;border:1px solid var(--line);border-radius:15px;overflow:hidden;display:flex;flex-direction:column;min-width:0}.pos-product.is-hidden{display:none}.pos-product-image{width:100%;aspect-ratio:16/8;object-fit:cover;background:#eee}.pos-product-body{padding:12px;display:flex;flex-direction:column;gap:7px;flex:1}.pos-product h3{margin:0;font-size:14px}.pos-product small{color:var(--muted)}.pos-price{font-weight:900;color:var(--accent)}.pos-controls{display:flex;align-items:center;gap:6px;margin-top:auto}.pos-controls button{width:37px;height:37px;min-height:37px;padding:0}.pos-controls .minus{background:#f1eff6;color:#6b6481}.pos-controls .plus{background:var(--accent);color:#fff}.pos-controls input{width:51px;min-height:37px;text-align:center;padding:6px}.pos-options{border-top:1px solid var(--line);padding-top:6px}.pos-options summary{font-size:10px;font-weight:850;color:#654bd4;cursor:pointer}.pos-option-group{padding:7px 0}.pos-option-group>strong{font-size:10px}.pos-option{display:flex;justify-content:space-between;gap:6px;align-items:center;font-size:10px;padding:4px 0}.pos-option input{width:auto;min-height:0}.pos-sale{position:sticky;top:18px}.pos-current-lines{display:grid;gap:7px;margin:12px 0;max-height:240px;overflow:auto}.pos-current-line{display:grid;grid-template-columns:1fr auto;gap:7px;padding:9px;border:1px solid var(--line);border-radius:11px}.pos-current-line small{display:block;color:var(--muted)}.pos-empty{text-align:center;color:var(--muted);padding:24px 8px}.pos-total{display:flex;justify-content:space-between;align-items:center;font-size:20px;font-weight:950;padding:13px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-bottom:13px}.pos-total strong{color:var(--accent)}.pos-sale-fields{display:grid;gap:10px}.pos-submit{width:100%;min-height:49px}.pos-partial-note{background:#f4f0ff;border:1px solid #e2d9ff;color:#5746a2;border-radius:12px;padding:10px;font-size:11px;margin-top:11px}.pos-stock-low{color:#c16b00;font-size:9px;font-weight:800}@media(max-width:1100px){.legacy-pos{grid-template-columns:1.4fr .7fr}.pos-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:820px){.legacy-pos{grid-template-columns:1fr}.pos-sale{position:static}.pos-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:460px){.pos-grid{grid-template-columns:1fr 1fr;gap:7px}.pos-product-body{padding:9px}.pos-product h3{font-size:12px}.pos-toolbar{align-items:stretch;flex-direction:column}.pos-controls button{width:34px}.pos-controls input{width:42px}}
</style>
<form method="post" id="legacyPosForm"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><div class="legacy-pos"><section class="pos-catalog"><div class="pos-toolbar"><div><h2 style="margin:0">Nova venda</h2><p class="muted" style="margin:4px 0 0">Selecione os produtos do pedido.</p></div><input class="pos-search" id="posSearch" type="search" placeholder="Buscar produto..."></div><div class="pos-categories"><button type="button" class="pos-cat active" data-cat="all">Todos</button><?php foreach($categories as$name=>$cid):?><button type="button" class="pos-cat" data-cat="<?= (int)$cid ?>"><?= Security::e($name) ?></button><?php endforeach;?></div><div class="pos-grid"><?php foreach($products as$product):$pid=(int)$product['id'];$base=$product['promo_price_cents']!==null?(int)$product['promo_price_cents']:(int)$product['price_cents'];?><article class="pos-product" data-product="<?= $pid ?>" data-cat="<?= (int)($product['category_id']??0) ?>" data-search="<?= Security::e(mb_strtolower((string)$product['name'].' '.(string)($product['description']??''))) ?>" data-name="<?= Security::e($product['name']) ?>" data-price="<?= $base ?>"><?php if(!empty($product['image_url'])):?><img class="pos-product-image" src="<?= Security::e($product['image_url']) ?>" alt="" loading="lazy"><?php endif;?><div class="pos-product-body"><div><h3><?= Security::e($product['name']) ?></h3><small><?= Security::e($product['category_name']??'Outros') ?></small></div><div class="pos-price"><?php if($product['promo_price_cents']!==null):?><s class="muted"><?= em_money($product['price_cents']) ?></s> <?php endif;?><?= em_money($base) ?></div><?php if((int)$product['track_stock']):?><small>Estoque: <?= Security::e((string)$product['stock_qty']) ?><?php if($product['min_stock_qty']!==null&&(float)$product['stock_qty']<=(float)$product['min_stock_qty']):?> <span class="pos-stock-low">baixo</span><?php endif;?></small><?php endif;?><?php if(!empty($groups[$pid])):?><details class="pos-options"><summary>Opções / adicionais</summary><?php foreach($groups[$pid] as$group):?><div class="pos-option-group" data-max="<?= (int)$group['max_select'] ?>"><strong><?= Security::e($group['name']) ?> · mín. <?= (int)$group['min_select'] ?> / máx. <?= (int)$group['max_select'] ?></strong><?php foreach($options[(int)$group['id']]??[]as$option):?><label class="pos-option"><span><input type="checkbox" name="option_ids[<?= $pid ?>][]" value="<?= (int)$option['id'] ?>" data-option-delta="<?= (int)$option['price_delta_cents'] ?>"> <?= Security::e($option['name']) ?></span><span><?= (int)$option['price_delta_cents']?(((int)$option['price_delta_cents']>0?'+ ':'- ').em_money(abs((int)$option['price_delta_cents']))):'' ?></span></label><?php endforeach;?></div><?php endforeach;?></details><?php endif;?><div class="pos-controls"><button class="minus" type="button" data-minus>-</button><input type="number" name="qty[<?= $pid ?>]" value="0" min="0" max="50" inputmode="numeric"><button class="plus" type="button" data-plus>+</button></div></div></article><?php endforeach;?></div><?php if(!$products):?><div class="card"><p class="muted">Nenhum produto ativo nesta unidade.</p></div><?php endif;?></section><aside class="card pos-sale"><div class="section-head"><div><h2>Pedido atual</h2><p class="muted" style="margin:4px 0 0">Balcão<?= $unitId?' · unidade #'.$unitId:'' ?></p></div><button type="button" class="secondary" id="posClear">Limpar</button></div><div class="pos-current-lines" id="posLines"><div class="pos-empty">Nenhum item adicionado.</div></div><div class="pos-total"><span>Total estimado</span><strong id="posTotal">R$ 0,00</strong></div><div class="pos-sale-fields"><label>Cliente<input name="customer_name" maxlength="160" placeholder="Opcional"></label><label>Telefone<input name="customer_phone" maxlength="30" autocomplete="tel" placeholder="Opcional"></label><label>Observações<textarea name="notes" maxlength="1000" placeholder="Ex.: cliente vai retirar aos poucos"></textarea></label><?php if(Auth::can('payments.manage')):?><label>Forma de pagamento<select name="manual_method"><option value="">Receber depois</option><option value="cash">Dinheiro</option><option value="card">Cartão / maquininha</option><option value="pix">Pix externo</option><option value="other">Outro</option></select></label><?php else:?><div class="alert">Seu perfil registra a venda, mas não confirma pagamento.</div><?php endif;?><button class="primary pos-submit"<?= !$products?' disabled':'' ?>>Finalizar venda</button></div><div class="pos-partial-note"><strong>Retirada parcial:</strong> se o cliente comprar 5 cervejas, poderá retirar 1 agora e as outras depois. O saldo fica registrado no comprovante.</div></aside></div></form>
<script>(function(){const cards=[...document.querySelectorAll('.pos-product')],search=document.getElementById('posSearch'),cats=[...document.querySelectorAll('.pos-cat')],lines=document.getElementById('posLines'),totalEl=document.getElementById('posTotal'),clear=document.getElementById('posClear');let activeCat='all';const money=c=>'R$ '+(c/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});const renderFilter=()=>{const q=(search?.value||'').trim().toLowerCase();cards.forEach(c=>c.classList.toggle('is-hidden',!(activeCat==='all'||c.dataset.cat===activeCat)||!!(q&&!c.dataset.search.includes(q))))};const renderCart=()=>{let html='',total=0;cards.forEach(card=>{const input=card.querySelector('input[name^="qty"]'),qty=Number(input?.value||0);if(qty<1)return;let unit=Number(card.dataset.price||0);card.querySelectorAll('[data-option-delta]:checked').forEach(o=>unit+=Number(o.dataset.optionDelta||0));const line=unit*qty;total+=line;html+='<div class="pos-current-line"><div><strong>'+card.dataset.name+'</strong><small>'+qty+' × '+money(unit)+'</small></div><strong>'+money(line)+'</strong></div>'});lines.innerHTML=html||'<div class="pos-empty">Nenhum item adicionado.</div>';totalEl.textContent=money(total)};cards.forEach(card=>{const input=card.querySelector('input[name^="qty"]');card.querySelector('[data-minus]')?.addEventListener('click',()=>{input.value=Math.max(0,Number(input.value||0)-1);renderCart()});card.querySelector('[data-plus]')?.addEventListener('click',()=>{input.value=Math.min(50,Number(input.value||0)+1);renderCart()});input?.addEventListener('input',renderCart);card.querySelectorAll('[data-option-delta]').forEach(x=>x.addEventListener('change',e=>{const group=e.target.closest('.pos-option-group'),max=Number(group?.dataset.max||99),checked=group?[...group.querySelectorAll('[data-option-delta]:checked')]:[];if(checked.length>max){e.target.checked=false;alert('Selecione no máximo '+max+' opção(ões) neste grupo.')}renderCart()}))});cats.forEach(b=>b.addEventListener('click',()=>{cats.forEach(x=>x.classList.remove('active'));b.classList.add('active');activeCat=b.dataset.cat;renderFilter()}));search?.addEventListener('input',renderFilter);clear?.addEventListener('click',()=>{cards.forEach(c=>{const q=c.querySelector('input[name^="qty"]');if(q)q.value=0;c.querySelectorAll('[data-option-delta]').forEach(o=>o.checked=false)});renderCart()});document.getElementById('legacyPosForm')?.addEventListener('submit',e=>{const any=cards.some(c=>Number(c.querySelector('input[name^="qty"]')?.value||0)>0);if(!any){e.preventDefault();alert('Adicione pelo menos um produto.')}});renderCart();})();</script>
